parameters.jsCode:
const body = $json.body || $json;

const name    = String(body.name    || '').trim().slice(0, 120);
const email   = String(body.email   || '').trim().slice(0, 160).toLowerCase();
const phone   = String(body.phone   || '').trim().slice(0, 40);
const message = String(body.message || '').trim().slice(0, 2000);
const locale  = String(body.locale  || '').trim().slice(0, 16) || 'pt-BR';

const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const valid   = !!name && emailOk && !!phone && !!message;

// lead_key estável: hash do email (mesmo email = mesmo lead_key)
const crypto  = require('crypto');
const leadKey = 'form_' + crypto.createHash('sha256').update(email).digest('hex').slice(0, 24);

return [{
  json: {
    valid,
    lead_key: leadKey,
    session_id: leadKey,
    source: 'form',
    nome: name,
    email,
    phone,
    briefing_completo: message,
    locale,
    status: 'novo',
    prioridade: 'media',
    step_funil: 'form_submitted',
    created_at: new Date().toISOString()
  }
}];

